import { Injectable, signal } from '@angular/core';

/** Tone của toast — khớp 5 tone của hrm-alert (appearance 'soft'). */
export type HrmToastTone = 'neutral' | 'info' | 'success' | 'warning' | 'error';

/** Một thẻ toast đang hiển thị. */
export interface HrmToastItem {
  id: number;
  tone: HrmToastTone;
  title: string;
  subtitle?: string;
}

/**
 * Hàng đợi toast transient (tự đóng sau duration + nút X).
 * Mount MỘT `<hrm-toast-outlet />` ở app root; gọi service ở bất kỳ đâu.
 */
@Injectable({ providedIn: 'root' })
export class HrmToastService {
  private readonly list = signal<HrmToastItem[]>([]);
  /** Danh sách toast đang hiển thị (readonly — outlet đọc để render). */
  readonly toasts = this.list.asReadonly();
  private seq = 0;
  /** Handle hẹn-giờ tự đóng theo id — để clearTimeout khi đóng sớm / clear (chống rò timer). */
  private readonly timers = new Map<number, ReturnType<typeof setTimeout>>();

  /** Hiện 1 toast; duration>0 tự đóng sau duration(ms), =0 giữ đến khi bấm X. Trả về id. */
  show(tone: HrmToastTone, title: string, subtitle?: string, duration = 4000): number {
    const id = ++this.seq;
    this.list.set([...this.list(), { id, tone, title, subtitle }]);
    if (duration > 0) {
      this.timers.set(id, setTimeout(() => this.dismiss(id), duration));
    }
    return id;
  }

  /** Tiện ích theo tone (title, phụ đề?, thời lượng?). */
  neutral(title: string, subtitle?: string, duration?: number): number {
    return this.show('neutral', title, subtitle, duration);
  }
  info(title: string, subtitle?: string, duration?: number): number {
    return this.show('info', title, subtitle, duration);
  }
  success(title: string, subtitle?: string, duration?: number): number {
    return this.show('success', title, subtitle, duration);
  }
  warning(title: string, subtitle?: string, duration?: number): number {
    return this.show('warning', title, subtitle, duration);
  }
  error(title: string, subtitle?: string, duration?: number): number {
    return this.show('error', title, subtitle, duration);
  }

  /** Đóng 1 toast theo id. */
  dismiss(id: number): void {
    const h = this.timers.get(id);
    if (h !== undefined) {
      clearTimeout(h);
      this.timers.delete(id);
    }
    this.list.set(this.list().filter((t) => t.id !== id));
  }

  /** Xoá toàn bộ toast. */
  clear(): void {
    this.timers.forEach((h) => clearTimeout(h));
    this.timers.clear();
    this.list.set([]);
  }
}
